using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // EF Core 9 renamed the discriminator property from "Discriminator" to "$type"
        // and changed id format from "Product|123" to "123".
        // Preserve EF8 conventions so existing 500K documents remain readable.
        optionsBuilder.UseCosmos(/* connection config */"",""/*placeholder*/,""/*placeholder*/,
            cosmosOptions => { });
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // BREAKING CHANGE 1 — Discriminator property renamed from "Discriminator" to "$type".
        // Pin to the old name so existing documents and raw SQL queries keep working.
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

        // BREAKING CHANGE 2 — Id format changed from "Product|123" to just "123".
        // Pin to the EF8 format so existing documents are still addressable.
        modelBuilder.Entity<Product>().HasPartitionKey(p => p.Id);
        modelBuilder.Entity<Product>()
            .Property(p => p.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.IdValueGenerator>();

        modelBuilder.Entity<Product>().ToContainer("Products");

        // BREAKING CHANGE 3 — HasIndex() now throws for Cosmos (was silently ignored in EF8).
        // Removed: modelBuilder.Entity<Product>().HasIndex(p => p.Sku);
        // Cosmos DB indexes are managed via the Azure indexing policy, not EF.
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

